  ('C-12-2','ISOWALL','12.2','ไม่มีอุปกรณ์ไม่ใช้งานหรือสิ่งที่ไม่เกี่ยวข้องบน ISOWALL','ค้อน ตะปู น็อต ปะแจ หรืออุปกรณ์อื่นๆ ไม่อยู่บน ISOWALL',array['production','warehouse']::area_type[],2,true),
