  ('C-13-2','บริเวณรอบอาคาร','13.2','ไม่มีวัชพืชขึ้นรก หญ้าไม่ยาวเกินไปรอบอาคาร','รอบอาคารไม่มีวัชพืชหรือหญ้ายาว',array['outdoor']::area_type[],2,true),
  ('C-13-3','บริเวณรอบอาคาร','13.3','ท่อระบายน้ำมีฝาปิด ไม่มีขยะ รางระบายไม่กีดขวาง','ระบบระบายน้ำสมบูรณ์ ไม่กีดขวางทางน้ำ',array['outdoor']::area_type[],2,true),
  ('C-13-4','บริเวณรอบอาคาร','13.4','โครงสร้างอาคารไม่ชำรุด ไม่เป็นแหล่งสัตว์พาหะ','มีแผนซ่อมถ้าชำรุด',array['outdoor']::area_type[],2,true),
  ('C-13-5','บริเวณรอบอาคาร','13.5','ประตูหนีไฟพร้อมใช้งาน มีป้ายชี้บ่ง ไม่มีสิ่งกีดขวาง','ประตูหนีไฟไม่ชำรุด ไม่เปิดทิ้งไว้',array['outdoor']::area_type[],2,true),
